const fs=require('fs');
function med(a){a=[...a].sort((a,b)=>a-b);return(a[3]+a[4])/2;}
const out=[];
for(let s=1;s<=2;s++){
 const p='experiments/parseatlas_secp256k1/data/p6_run'+s+'_20260905.json';
 const j=JSON.parse(fs.readFileSync(p,'utf8'));
 const later=j.regions.filter(r=>r.phase!=='calibration'), rows=[];
 for(const c of j.cells){const rs=j.regions.filter(r=>r.cell===c.id&&r.phase==='measurement').sort((a,b)=>a.round-b.round); rows.push({id:c.id,route:c.route,mode:c.mode,ns:med(rs.map(r=>r.elapsed_ns/r.operations)),min:Math.min(...rs.map(r=>r.elapsed_ns/r.operations)),max:Math.max(...rs.map(r=>r.elapsed_ns/r.operations)),zero:c.trace_zero_states,one:c.trace_one_states});}
 const comparisons={};
 for(const kind of ['primary_comparisons','secondary_comparisons','mode_comparisons']){
 comparisons[kind]=j[kind].map(c=>{let wins=0;const ratios=[];for(let r=0;r<8;r++){let a=j.regions.find(x=>x.phase==='measurement'&&x.cell===c.numerator_cell&&x.round===r),b=j.regions.find(x=>x.phase==='measurement'&&x.cell===c.denominator_cell&&x.round===r);const ratio=(a.elapsed_ns/a.operations)/(b.elapsed_ns/b.operations);ratios.push(ratio);wins+=ratio>1;}return{a:c.numerator_cell,b:c.denominator_cell,ratio:med(ratios),wins,min:Math.min(...ratios),max:Math.max(...ratios)};});}
 out.push({series:s,status:j.status,hash:j.corpus.checksum_fnv1a64,regions:j.regions.length,cal:j.regions.filter(r=>r.phase==='calibration').length,shortcal:j.regions.filter(r=>r.phase==='calibration'&&!r.floor_met).length,warm:later.filter(r=>r.phase==='warmup').length,measured:later.filter(r=>r.phase==='measurement').length,minimum_later_ns:Math.min(...later.map(r=>r.elapsed_ns)),shortlater:later.filter(r=>r.elapsed_ns<200000000).length,extensions:later.reduce((a,r)=>a+r.extensions,0),extendedregions:later.filter(r=>r.extensions>0).length,probes:j.regions.reduce((a,r)=>a+r.clock_checks,0),allverified:j.regions.every(r=>r.verified&&r.actual_final_be128===j.cells[r.cell].expected_final_be128),cpus:[...new Set(j.regions.flatMap(r=>[r.cpu_start,r.cpu_end]))],rows,comparisons});
}process.stdout.write(JSON.stringify(out));

final_gate_js:
const fs=require('fs'),crypto=require('crypto'),path=require('path');
const base='experiments/parseatlas_secp256k1/',manifest=JSON.parse(fs.readFileSync(base+'data/p6_build_20260905.json','utf8'));
const errors=[],counts={p6_hashes:0,p2_hashes:0,p3_hashes:0,p4_hashes:0,p5_hashes:0,text_files:0,links:0,lens_rows:0};const sha=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
for(const h of manifest.hashed_files){counts.p6_hashes++;if(sha(h.path)!==h.sha256)errors.push('P6 hash '+h.path);}
for(const n of [2,3,4,5]){const old=JSON.parse(fs.readFileSync(base+'data/p'+n+'_build_20260905.json','utf8'));for(const h of old.hashed_files){const p=h.path===base+'RESEARCH_FRONTIER.md'?base+'data/p'+n+'_frontier_snapshot_20260905.md':h.path;counts['p'+n+'_hashes']++;if(sha(p)!==h.sha256)errors.push('historical hash '+p);}}
const docs=manifest.hashed_files.filter(h=>h.path.startsWith(base)&&/\.(md|hpp|cpp)$/.test(h.path)&&!h.path.includes('_frontier_snapshot_'));
for(const h of docs){const t=fs.readFileSync(h.path,'utf8'),ls=t.split('\n');counts.text_files++;if(!t.endsWith('\n'))errors.push('no final newline '+h.path);for(let i=0;i<ls.length;i++)if(/[ \t]+$/.test(ls[i]))errors.push('trailing whitespace '+h.path+':'+(i+1));
 if(!h.path.endsWith('.md'))continue;
 for(const m of t.matchAll(/\[[^\]]+\]\(([^)]+)\)/g)){let target=m[1];if(/^(?:https?:|#|mailto:)/.test(target))continue;target=target.replace(/^<|>$/g,'').split('#')[0];if(!target)continue;const p=path.resolve(path.dirname(h.path),target);counts.links++;if(!fs.existsSync(p))errors.push('missing link '+h.path+' => '+target);}
}
const lens=p=>fs.readFileSync(base+p,'utf8').split('\n').filter(l=>/^\| V\d\d /.test(l)).map(l=>l.split('|')[1].trim());
const a=lens('P6_FIELD_BOUNDARY_LENSES.md'),b=lens('P6_FIELD_BOUNDARY_LENS_RESULTS.md'),c=lens('P5_FIELD_PRODUCT_LENS_RESULTS.md');
counts.lens_rows=b.length;if(a.length!==25||b.length!==25||JSON.stringify(a)!==JSON.stringify(b)||JSON.stringify(b)!==JSON.stringify(c))errors.push('lens identity mismatch');
const freeze=JSON.parse(fs.readFileSync(base+'data/p6_performance_freeze_20260905.json','utf8'));for(const[p,h]of Object.entries(freeze.hashed_files))if(sha(p)!==h)errors.push('prefreeze hash '+p);
const audit=JSON.parse(fs.readFileSync(base+'data/p6_numeric_audit_20260905.json','utf8'));if(audit.status!=='pass'||audit.check_count!==42411||audit.error_count!==0)errors.push('audit status');
const replay=JSON.parse(fs.readFileSync(base+'data/p6_numeric_replay_20260905.json','utf8'));if(!replay.full_object_equality||replay.audit_sha256!==sha(base+'data/p6_numeric_audit_20260905.json'))errors.push('audit replay binding');
const code=JSON.parse(fs.readFileSync(base+'data/p6_codegen_replay_20260905.json','utf8'));if(code.status!=='pass'||code.checks!==10521||code.codegen_sha256!==sha(base+'data/p6_codegen_20260905.json'))errors.push('codegen replay binding');
console.log(JSON.stringify({schema:'parseatlas.p6.final_mechanical_gate.v1',status:errors.length?'fail':'pass',counts,errors,manifest_sha256:sha(base+'data/p6_build_20260905.json')}));
if(errors.length)process.exitCode=1;
